/**
 * RP-03 Cannon-es 0.20.0 边界探针。
 * 不修改 src/。单位：m, kg, s, N, rad。
 * 轮胎半径取项目默认 245/35 R20 的几何推导，不是某量产车测量值。
 */
import { readFileSync, writeFileSync } from 'node:fs';
import * as CANNON from 'file:///F:/project/cyq/AI_Coding/car/node_modules/cannon-es/dist/cannon-es.js';
import { CAR_CONFIG, TIRE_SPECS, deriveDimensions } from 'file:///F:/project/cyq/AI_Coding/car/src/specs.js';

const DT = 1 / 60;
const radius = deriveDimensions(TIRE_SPECS[0]).outerRadius;
const outPath = 'F:/project/cyq/AI_Coding/car/docs/planning/evidence/RP-03-cannon-probe.json';

function quatAngle(a, b) {
  const dot = Math.abs(a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w);
  return 2 * Math.acos(Math.min(1, dot));
}

function yawOf(q) {
  const siny = 2 * (q.w * q.y + q.x * q.z);
  const cosy = 1 - 2 * (q.y * q.y + q.z * q.z);
  return Math.atan2(siny, cosy);
}

function makeWorld(frictionSlip, wheelbase) {
  const world = new CANNON.World({ gravity: new CANNON.Vec3(0, -9.81, 0) });
  world.broadphase = new CANNON.SAPBroadphase(world);
  world.allowSleep = false;
  const ground = new CANNON.Body({ mass: 0 });
  ground.addShape(new CANNON.Plane());
  ground.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
  world.addBody(ground);

  const chassis = new CANNON.Body({
    mass: CAR_CONFIG.mass,
    linearDamping: 0,
    angularDamping: 0
  });
  chassis.addShape(new CANNON.Box(new CANNON.Vec3(0.56, 0.17, 1.46)));
  const vehicle = new CANNON.RaycastVehicle({
    chassisBody: chassis,
    indexRightAxis: 0,
    indexUpAxis: 1,
    indexForwardAxis: 2
  });
  const halfWB = wheelbase / 2;
  const halfTrack = CAR_CONFIG.halfTrack;
  const susp = CAR_CONFIG.suspension;
  const anchors = [
    [halfTrack, CAR_CONFIG.chassisConnY, halfWB],
    [-halfTrack, CAR_CONFIG.chassisConnY, halfWB],
    [halfTrack, CAR_CONFIG.chassisConnY, -halfWB],
    [-halfTrack, CAR_CONFIG.chassisConnY, -halfWB]
  ];
  for (const [x, y, z] of anchors) {
    vehicle.addWheel({
      radius,
      directionLocal: new CANNON.Vec3(0, -1, 0),
      axleLocal: new CANNON.Vec3(-1, 0, 0),
      suspensionStiffness: susp.stiffness,
      suspensionRestLength: susp.restLength,
      frictionSlip,
      dampingRelaxation: susp.dampingRelaxation,
      dampingCompression: susp.dampingCompression,
      maxSuspensionForce: 90000,
      rollInfluence: susp.rollInfluence,
      maxSuspensionTravel: susp.maxTravel,
      chassisConnectionPointLocal: new CANNON.Vec3(x, y, z),
      customSlidingRotationalSpeed: -24,
      useCustomSlidingRotationalSpeed: true
    });
  }
  vehicle.addToWorld(world);
  chassis.position.set(
    0,
    radius + susp.restLength - CAR_CONFIG.chassisConnY + 0.02,
    0
  );
  chassis.quaternion.set(0, 0, 0, 1);
  chassis.velocity.set(0, 0, 0);
  chassis.angularVelocity.set(0, 0, 0);
  return { world, vehicle, chassis, ground };
}

function stepN(world, n) {
  for (let i = 0; i < n; i++) world.step(DT);
}

function settle(bundle, seconds = 3) {
  stepN(bundle.world, Math.round(seconds / DT));
}

function armSpan(suspLen, side = 1) {
  const z = CAR_CONFIG.wheelbase / 2;
  const hubX = side * CAR_CONFIG.halfTrack;
  const hubY = CAR_CONFIG.chassisConnY - suspLen;
  const upperEnd = { x: hubX - side * 0.14, y: hubY + 0.09, z };
  const lowerEnd = { x: hubX - side * 0.14, y: hubY - 0.085, z };
  const upperPivot = { x: side * 0.29, y: 0.11, z };
  const lowerPivot = { x: side * 0.27, y: -0.09, z };
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
  return {
    upper: dist(upperPivot, upperEnd),
    lower: dist(lowerPivot, lowerEnd)
  };
}

function projectSteer(s) {
  return { FL: s, FR: s * 0.94 };
}

function ackermannInner(outer) {
  const track = CAR_CONFIG.halfTrack * 2;
  const wheelbase = CAR_CONFIG.wheelbase;
  const cotInner = 1 / Math.tan(outer) - track / wheelbase;
  return Math.atan(1 / cotInner);
}

const tests = [];
function add(id, pass, detail) {
  tests.push({ id, pass: Boolean(pass), ...detail });
}

const tire = deriveDimensions(TIRE_SPECS[0]);
const base = makeWorld(CAR_CONFIG.suspension.frictionSlip, CAR_CONFIG.wheelbase);

add('wheel_not_rigid_body', base.world.bodies.length === 2 && base.vehicle.wheelInfos.length === 4, {
  worldBodyCount: base.world.bodies.length,
  wheelInfoCount: base.vehicle.wheelInfos.length,
  wheelHasBody: base.vehicle.wheelInfos.some((w) => w.body != null),
  expect: '只有地面和车身两个刚体；四个轮子是 WheelInfo，没有 body'
});

const camberAngles = [];
for (const L of [0.12, 0.34, 0.5]) {
  base.vehicle.wheelInfos[0].suspensionLength = L;
  base.vehicle.wheelInfos[0].steering = 0;
  base.vehicle.wheelInfos[0].rotation = 0;
  base.vehicle.updateWheelTransform(0);
  camberAngles.push(quatAngle(
    base.vehicle.getWheelTransformWorld(0).quaternion,
    base.chassis.quaternion
  ));
}
add('camber_unchanged_by_travel', Math.max(...camberAngles) < 1e-8, {
  angleRad: camberAngles,
  expect: '行程改变时，轮子相对车身的姿态角保持 0（无外倾变化）'
});

base.vehicle.wheelInfos[0].steering = 0.4;
base.vehicle.wheelInfos[0].rotation = 0;
base.vehicle.updateWheelTransform(0);
const fwd = new CANNON.Vec3();
base.vehicle.getWheelTransformWorld(0).vectorToWorldFrame(new CANNON.Vec3(0, 0, 1), fwd);
add('positive_steer_yaws_toward_positive_x', fwd.x > 0.3 && fwd.z > 0.8, {
  wheelForward: { x: fwd.x, y: fwd.y, z: fwd.z },
  expect: '正转向角使轮子朝 +X（本项目左轮一侧）偏航'
});

const restL = CAR_CONFIG.suspension.restLength;
const bumpL = restL - CAR_CONFIG.suspension.maxTravel;
const spanRest = armSpan(restL);
const spanBump = armSpan(bumpL);
add('visual_wishbone_changes_length', Math.abs(spanRest.upper - spanBump.upper) > 0.01, {
  spanAtRest_m: spanRest,
  spanAtBump_m: spanBump,
  upperDelta_mm: (spanRest.upper - spanBump.upper) * 1000,
  lowerDelta_mm: (spanRest.lower - spanBump.lower) * 1000,
  expect: '按 chassis.js 的枢轴和球头公式，跳动后上下叉臂长度变化超过 10 mm'
});

const outer = 0.3;
const inner = ackermannInner(outer);
const left = projectSteer(outer);
const right = projectSteer(-outer);
add('ackermann_factor_is_not_geometric', true, {
  note: '本项记录对比，不把当前 0.94 系数判为合格的阿克曼',
  track_m: CAR_CONFIG.halfTrack * 2,
  wheelbase_m: CAR_CONFIG.wheelbase,
  geometricInnerForOuter0_3_rad: inner,
  geometricInnerOverOuter: inner / outer,
  projectLeftTurn: left,
  projectRightTurn: right,
  projectMagnitudeRatio: Math.abs(left.FL / left.FR),
  wrongWheelOnRightTurn: Math.abs(right.FL) > Math.abs(right.FR),
  expect: '右转时内侧轮应是 FR，但 0.94 始终缩小 FR，所以外侧轮转角更大'
});

const airborne = makeWorld(CAR_CONFIG.suspension.frictionSlip, CAR_CONFIG.wheelbase);
airborne.chassis.position.y = 4;
airborne.chassis.velocity.set(0, 5, 0);
airborne.vehicle.updateVehicle(DT);
const speedUp = airborne.vehicle.currentVehicleSpeedKmHour;
airborne.chassis.velocity.set(0, 0, 5);
airborne.vehicle.updateVehicle(DT);
const speedFwd = airborne.vehicle.currentVehicleSpeedKmHour;
add('speed_uses_velocity_magnitude', Math.abs(speedUp - 18) < 1e-6 && Math.abs(speedFwd - 18) < 1e-6, {
  vertical5mps_kmh: speedUp,
  forward5mps_kmh: speedFwd,
  expect: '竖直 5 m/s 与向前 5 m/s 得到同一个 18 km/h'
});

let maxLen = 0;
const drop = makeWorld(CAR_CONFIG.suspension.frictionSlip, CAR_CONFIG.wheelbase);
drop.chassis.position.y = 1.6;
for (let i = 0; i < 180; i++) {
  drop.world.step(DT);
  for (const w of drop.vehicle.wheelInfos) maxLen = Math.max(maxLen, w.suspensionLength);
}
add('no_droop_beyond_rest', maxLen <= CAR_CONFIG.suspension.restLength + 1e-6, {
  maxSuspensionLength_m: maxLen,
  restLength_m: CAR_CONFIG.suspension.restLength,
  expect: '下落过程中悬架长度不超过静止长度；射线模型没有下垂行程'
});

const settled = makeWorld(CAR_CONFIG.suspension.frictionSlip, CAR_CONFIG.wheelbase);
settle(settled, 4);
const lengths = settled.vehicle.wheelInfos.map((w) => w.suspensionLength);
const forces = settled.vehicle.wheelInfos.map((w) => w.suspensionForce);
const predicted = CAR_CONFIG.suspension.restLength - 9.81 / (4 * CAR_CONFIG.suspension.stiffness);
const meanLen = lengths.reduce((s, v) => s + v, 0) / lengths.length;
add('spring_force_is_stiffness_times_mass', Math.abs(meanLen - predicted) < 0.005, {
  predictedLength_m: predicted,
  lengths_m: lengths,
  forces_N: forces,
  effectiveStiffness_N_per_m: CAR_CONFIG.suspension.stiffness * CAR_CONFIG.mass,
  expect: '静平衡压缩量等于 g/(4*stiffness)，说明刚度先乘整车质量'
});

function runCoast() {
  const b = makeWorld(CAR_CONFIG.suspension.frictionSlip, CAR_CONFIG.wheelbase);
  settle(b, 3);
  b.chassis.velocity.set(0, 0, 8);
  b.chassis.angularVelocity.set(0, 0, 0);
  for (const w of b.vehicle.wheelInfos) {
    w.brake = 0;
    w.engineForce = 0;
  }
  stepN(b.world, 60);
  return b.chassis.velocity.z;
}
const coastVz = runCoast();
add('coast_has_no_tire_rolling_resistance', Math.abs(coastVz - 8) < 0.05, {
  vzAfter1s_m_per_s: coastVz,
  frictionSlip: CAR_CONFIG.suspension.frictionSlip,
  expect: '不踩刹车、不给驱动力时，1 秒后纵向速度仍接近 8 m/s'
});

function runBrake(frictionSlip, brake, seconds, v0 = 10) {
  const b = makeWorld(frictionSlip, CAR_CONFIG.wheelbase);
  settle(b, 3);
  b.chassis.velocity.set(0, 0, v0);
  b.chassis.angularVelocity.set(0, 0, 0);
  const rot0 = b.vehicle.wheelInfos.map((w) => w.rotation);
  for (const w of b.vehicle.wheelInfos) {
    w.brake = brake;
    w.engineForce = 0;
  }
  const n = Math.round(seconds / DT);
  stepN(b.world, n);
  const rot1 = b.vehicle.wheelInfos.map((w) => w.rotation);
  return {
    vz: b.chassis.velocity.z,
    z: b.chassis.position.z,
    rotationDelta: rot1.map((r, i) => r - rot0[i]),
    sliding: b.vehicle.wheelInfos.map((w) => w.sliding)
  };
}

const brakeHigh = runBrake(3.2, 30, 2);
const brakeLow = runBrake(0.08, 30, 2);
add('straight_brake_ignores_frictionSlip', Math.abs(brakeHigh.vz - brakeLow.vz) < 1e-9, {
  hypothesisBeforeRun: '直线制动时，较小的 frictionSlip 应该留下更高的末速度',
  hypothesisHeld: false,
  brakeImpulseCap: 30,
  highFrictionSlip: brakeHigh,
  lowFrictionSlip: brakeLow,
  codeReason: 'cannon-es updateFriction 仅在 sideImpulse 非 0 时才用 skidInfo 缩小 forwardImpulse；直线上侧向冲量为 0，frictionSlip 不参与这次刹车',
  expect: 'frictionSlip 3.2 与 0.08 的直线刹车末速度相同',
  limitation: '因此不能把 frictionSlip 当成冰面摩擦系数。直线制动距离不能用来证明附着变化'
});

function runSteeredBrake(frictionSlip) {
  const b = makeWorld(frictionSlip, CAR_CONFIG.wheelbase);
  settle(b, 3);
  b.chassis.velocity.set(0, 0, 10);
  b.chassis.angularVelocity.set(0, 0, 0);
  b.vehicle.setSteeringValue(0.35, 0);
  b.vehicle.setSteeringValue(0.35, 1);
  for (const w of b.vehicle.wheelInfos) {
    w.brake = 30;
    w.engineForce = 0;
  }
  stepN(b.world, 90);
  return {
    vz: b.chassis.velocity.z,
    vx: b.chassis.velocity.x,
    yaw: yawOf(b.chassis.quaternion),
    speed: Math.hypot(b.chassis.velocity.x, b.chassis.velocity.z),
    sliding: b.vehicle.wheelInfos.map((w) => w.sliding)
  };
}
const steeredHigh = runSteeredBrake(3.2);
const steeredLow = runSteeredBrake(0.08);
add('steered_brake_speed_depends_on_frictionSlip',
  Math.abs(steeredHigh.speed - steeredLow.speed) > 0.2, {
  highFrictionSlip: steeredHigh,
  lowFrictionSlip: steeredLow,
  expect: '前轮同向偏转 0.35 rad 并制动时，两种 frictionSlip 的水平速度不同',
  limitation: '这只说明该参数在有侧向冲量时会进入打滑缩放，仍然不是冰的库仑摩擦系数，也没有水面阻力'
});

const spinSum = brakeLow.rotationDelta.reduce((s, v) => s + Math.abs(v), 0);
add('brake_freezes_wheel_rotation_while_sliding', spinSum < 1e-6 && brakeLow.z > 5, {
  rotationDelta_rad: brakeLow.rotationDelta,
  travelZ_m: brakeLow.z,
  expect: '只要刹车量大于驱动力，轮子转角增量被置零，即使车身仍在滑行'
});

function runSteer(wheelbase) {
  const b = makeWorld(1.2, wheelbase);
  settle(b, 2);
  b.chassis.velocity.set(0, 0, 8);
  b.chassis.angularVelocity.set(0, 0, 0);
  b.vehicle.setSteeringValue(0.25, 0);
  b.vehicle.setSteeringValue(0.25, 1);
  stepN(b.world, 60);
  return {
    yaw_rad: yawOf(b.chassis.quaternion),
    steer: [b.vehicle.wheelInfos[0].steering, b.vehicle.wheelInfos[1].steering]
  };
}
const yawShort = runSteer(CAR_CONFIG.wheelbase);
const yawLong = runSteer(3.2);
add('wheelbase_changes_yaw_not_steer_angles',
  Math.abs(yawShort.yaw_rad) > Math.abs(yawLong.yaw_rad) + 0.01
  && yawShort.steer[0] === 0.25 && yawLong.steer[0] === 0.25
  && yawShort.steer[1] === 0.25 && yawLong.steer[1] === 0.25, {
  wheelbase2_46: yawShort,
  wheelbase3_20: yawLong,
  expect: '轴距变长会减小同样转角下的偏航，但转向角不会因轴距自动改写'
});

const detA = runBrake(0.08, 30, 1);
const detB = runBrake(0.08, 30, 1);
add('fixed_step_repeatable', Math.abs(detA.z - detB.z) < 1e-9 && Math.abs(detA.vz - detB.vz) < 1e-9, {
  runA: { z: detA.z, vz: detA.vz },
  runB: { z: detB.z, vz: detB.vz }
});

const roll = makeWorld(3.2, CAR_CONFIG.wheelbase);
settle(roll, 2);
roll.chassis.velocity.set(0, 0, 6);
roll.vehicle.updateVehicle(DT);
const deltaRot = roll.vehicle.wheelInfos[0].deltaRotation;
add('forward_plus_z_makes_negative_wheel_delta', deltaRot < 0, {
  deltaRotation_rad: deltaRot,
  expect: '车身速度朝 +Z 时，求解器给轮子的转角增量是负数'
});

function piston(theta, r, l) {
  return r * Math.cos(theta) + Math.sqrt(l * l - (r * Math.sin(theta)) ** 2);
}
const crankR = 0.045;
const rodL = 0.15;
const x0 = piston(0, crankR, rodL);
const x90 = piston(Math.PI / 2, crankR, rodL);
const x180 = piston(Math.PI, crankR, rodL);
const x270 = piston(3 * Math.PI / 2, crankR, rodL);
add('slider_crank_position_only',
  Math.abs(x0 - (crankR + rodL)) < 1e-12
  && Math.abs(x180 - (-crankR + rodL)) < 1e-12
  && Math.abs(x90 - x270) < 1e-12
  && x0 > x180, {
  fixture: { crankRadius_m: crankR, rodLength_m: rodL, label: '虚构机构，不是某台发动机' },
  positionFromCrankCenter_m: { tdc: x0, at90: x90, bdc: x180, at270: x270 },
  torque_N_m: null,
  pressure_Pa: null,
  expect: '只验证曲柄滑块位置；扭矩和缸压没有被计算'
});

const failed = tests.filter((t) => !t.pass).map((t) => t.id);
const payload = {
  schema: 'carlab.rp03.cannonProbe.v1',
  task: 'RP-03',
  date: '2026-11-14',
  command: 'node F:\\tmp\\rp03-probe.mjs',
  cannonPackage: 'cannon-es@0.20.0',
  sourceFile: 'node_modules/cannon-es/dist/cannon-es.js',
  dt_s: DT,
  units: { length: 'm', mass: 'kg', time: 's', force: 'N', angle: 'rad' },
  fixture: {
    mass_kg: CAR_CONFIG.mass,
    wheelbase_m: CAR_CONFIG.wheelbase,
    halfTrack_m: CAR_CONFIG.halfTrack,
    suspension: CAR_CONFIG.suspension,
    tireSpec: TIRE_SPECS[0].spec,
    tireOuterRadius_m: radius,
    tireRimRadius_m: tire.rimRadius,
    tireNote: '半径由 245/35 R20 的名义公式算出，品牌 VULCAN 是项目虚构名称'
  },
  passCount: tests.length - failed.length,
  failCount: failed.length,
  failed,
  tests,
  probeSource: readFileSync(new URL(import.meta.url), 'utf8')
};

writeFileSync(outPath, JSON.stringify(payload, null, 2));
console.log(JSON.stringify({
  passCount: payload.passCount,
  failCount: payload.failCount,
  failed,
  highlights: {
    upperDelta_mm: tests.find((t) => t.id === 'visual_wishbone_changes_length').upperDelta_mm,
    meanLen: meanLen,
    predicted,
    coastVz,
    brakeHighVz: brakeHigh.vz,
    brakeLowVz: brakeLow.vz,
    brakeLowZ: brakeLow.z,
    steeredHighSpeed: steeredHigh.speed,
    steeredLowSpeed: steeredLow.speed,
    yawShort: yawShort.yaw_rad,
    yawLong: yawLong.yaw_rad,
    speedUp,
    maxLen,
    deltaRot
  }
}, null, 2));
